def _parse_response_impl[Output](response: str, prompt: Prompt[Output, Any]) -> Output:
    output_format = prompt.output_format
    match output_format.format:
        case "json":
            response = response.strip()
            if response.startswith("```"):
                # Remove code fences (``` or ```json) from start and end
                response = re.sub(
                    r"^```(?:json)?\s*\n?(.*?)\n?```$",
                    r"\1",
                    response,
                    flags=re.DOTALL,
                ).strip()

            try:
                return output_format.type_adapter.validate_json(response, by_alias=True)
            except Exception as e:
                raise type(e)(f"Template '{prompt.template_id}': {e}") from e

        case "text":
            return cast(Output, response)


def _make_tool_error_response(call_id: str, error_message: str) -> ToolCallResponse:
    error_json = json.dumps({"error": error_message})
    return ToolCallResponse(
        call_id=call_id,
        stringified_output=error_json,
        error=error_message,
    )


async def _execute_tools_impl[ToolExecutor](
    tool_calls: Iterable[ToolCall],
    namespace: str,
    executor: ToolExecutor,
    prompt: Prompt[Any, ToolExecutor],
) -> Sequence[ToolCallResponse]:
    import asyncio

    async def _execute_one(call: ToolCall) -> ToolCallResponse:
        tool = prompt.tools.get(call.tool_name)
        if tool is None:
            return _make_tool_error_response(
                call.call_id, f"Tool not found: {call.tool_name}"
            )
        tool_id = f"{namespace}:{call.tool_name}"
        method_name = _TOOL_ID_TO_METHOD_NAME.get(tool_id)
        impl = (
            getattr(executor, method_name, None)
            if method_name and executor is not None
            else None
        )
        if impl is None:
            return _make_tool_error_response(
                call.call_id, f"Tool implementation not found: {call.tool_name}"
            )
        try:
            input = tool.input_adapter.validate_json(
                call.stringified_input, by_alias=True
            )
        except Exception as e:
            return _make_tool_error_response(
                call.call_id, f"Failed to parse tool input: {e}"
            )
        try:
            raw_output = await impl(input)
            stringified_output = tool.output_adapter.dump_json(
                raw_output, by_alias=True
            ).decode()
            return ToolCallResponse(
                call_id=call.call_id,
                stringified_output=stringified_output,
            )
        except Exception as e:
            return _make_tool_error_response(call.call_id, str(e))

    return await asyncio.gather(*(_execute_one(call) for call in tool_calls))


@dataclass(frozen=True)
class _TemplateImpl[Input, Output, ToolExecutor]:
    _template_id: TemplateId
    _template_data: _internal.Template
    _data: _internal.Templates

    def render(self, input: Input) -> Prompt[Output, ToolExecutor]:
        def evaluate(expression: _internal.Expression, val: Any) -> Any:
            match expression.kind:
                case "input":
                    return val
                case "property":
                    obj = evaluate(expression.left, val)
                    return cast(dict, obj).get(expression.property)

        def indent(text: str, spaces: str) -> str:
            if not spaces:
                return text
            return text.replace("\n", "\n" + spaces)

        def format_table(v: Any, fmt: Literal["csv", "tsv"]) -> str:
            separator = "," if fmt == "csv" else "\t"
            rows = cast(list[dict], v)
            if not rows:
                return ""
            header = list(rows[0].keys())
            lines = [separator.join(header)]
            for row in rows:
                cells = row.values()
                if fmt == "csv":

                    def csv_cell(c: Any) -> str:
                        s = str(c)
                        return (
                            '"' + s.replace('"', '""') + '"'
                            if re.search(r'[",\n\r]', s)
                            else s
                        )

                    lines.append(separator.join(csv_cell(c) for c in cells))
                else:

                    def tsv_cell(c: Any) -> str:
                        return (
                            str(c)
                            .replace("\\", "\\\\")
                            .replace("\t", "\\t")
                            .replace("\n", "\\n")
                            .replace("\r", "\\r")
                        )

                    lines.append(separator.join(tsv_cell(c) for c in cells))
            return "\n".join(lines)

        def format_value(v: Any, fmt: _internal.InsertFormat | None) -> str:
            match fmt:
                case None | "text":
                    return str(v)
                case "json":
                    return json.dumps(v, indent=2)
                case "yaml":
                    return yaml.dump(
                        v,
                        allow_unicode=True,
                        default_flow_style=False,
                        sort_keys=False,
                    ).rstrip("\n")
                case "toon":
                    return toon_format.encode(v)
                case "csv" | "tsv":
                    return format_table(v, fmt)

        def render_body(
            body: Sequence[_internal.BodyPiece],
            inp: Any,
            snippets: Mapping[str, _internal.Snippet],
            typescript_schema: str,
        ) -> str:
            parts: list[str] = []
            for piece in body:
                match piece.kind:
                    case "text":
                        parts.append(piece.text)
                    case "insert-val":
                        parts.append(
                            indent(
                                format_value(evaluate(piece.val, inp), piece.format),
                                piece.indent,
                            )
                        )
                    case "insert-snippet":
                        snippet = snippets.get(piece.snippet)
                        if snippet is None:
                            raise ValueError(f"Snippet not found: {piece.snippet}")
                        parts.append(
                            indent(
                                render_snippet(
                                    snippet, inp, snippets, typescript_schema
                                ),
                                piece.indent,
                            )
                        )
                    case "insert-schema":
                        parts.append(indent(typescript_schema, piece.indent))
            return "".join(parts)

        def render_snippet(
            snippet: _internal.Snippet,
            inp: Any,
            snippets: Mapping[str, _internal.Snippet],
            typescript_schema: str,
        ) -> str:
            match snippet.kind:
                case "snippet":
                    return render_body(snippet.body, inp, snippets, typescript_schema)
                case "snippet-if":
                    eval_result = evaluate(snippet.expression, inp)
                    match snippet.is_:
                        case "not-empty":
                            condition = len(eval_result) > 0
                        case "not-null":
                            condition = eval_result is not None
                        case "true":
                            condition = bool(eval_result)
                    return render_body(
                        snippet.then if condition else snippet.else_,
                        inp,
                        snippets,
                        typescript_schema,
                    )
                case "snippet-switch":
                    eval_result = evaluate(snippet.expression, inp)
                    branch = snippet.branches.get(str(eval_result))
                    if branch is None:
                        raise ValueError(f"Branch not found: {eval_result}")
                    return render_body(branch, inp, snippets, typescript_schema)

        def render_examples(
            examples: Sequence[_internal.FewShotExample],
            user_body: Sequence[_internal.BodyPiece],
            tmpl: _internal.Template,
            typescript_schema: str,
        ) -> Sequence[FewShotExample]:
            result = []
            for ex in examples:
                result.append(
                    FewShotExample(
                        user_message=render_body(
                            user_body, ex.input, tmpl.snippets, typescript_schema
                        ),
                        steps=[
                            StepExample(
                                tool_calls=[
                                    ToolCallExample(
                                        call_id=tc.call_id,
                                        tool_name=tc.tool_name,
                                        stringified_input=json.dumps(tc.input),
                                        stringified_output=json.dumps(tc.output),
                                    )
                                    for tc in step.tool_calls
                                ]
                            )
                            for step in ex.steps
                        ],
                        response=format_value(ex.output, tmpl.output_format.format),
                    )
                )
            return result

        input_adapter, output_adapter = _type_adapters[self._template_id]
        input_val = input_adapter.dump_python(cast(Any, input), by_alias=True)
        del input

        template = self._template_data
        snippets = template.snippets
        contents = template.contents
        typescript_schema = (
            template.output_format.typescript_schema
            if template.output_format.format == "json"
            else ""
        )

        if contents.kind == "no-variants":
            content = contents.content
            meta = _meta_type_adapter.validate_python(content.meta, by_alias=True)
            system_message = render_body(
                content.system or [], input_val, snippets, typescript_schema
            )
            user_body = content.user or []
            user_message = render_body(
                user_body, input_val, snippets, typescript_schema
            )
            examples = render_examples(
                content.examples or [], user_body, template, typescript_schema
            )
        else:
            variant = cast(dict, input_val)["variant"]
            variant_content = contents.variants[variant]
            default_content = contents.default_content
            meta = _meta_type_adapter.validate_python(
                variant_content.meta
                if variant_content.meta is not None
                else default_content.meta,
                by_alias=True,
            )
            system_body = (
                variant_content.system
                if variant_content.system is not None
                else (default_content.system or [])
            )
            user_body = (
                variant_content.user
                if variant_content.user is not None
                else (default_content.user or [])
            )
            system_message = render_body(
                system_body, input_val, snippets, typescript_schema
            )
            user_message = render_body(
                user_body, input_val, snippets, typescript_schema
            )
            raw_examples = (
                variant_content.examples
                if variant_content.examples is not None
                else (default_content.examples or [])
            )
            examples = render_examples(
                raw_examples, user_body, template, typescript_schema
            )

        def make_tool(tool_spec: _internal.TemplateTool) -> Tool:
            input_adapter, output_adapter = _type_adapters[tool_spec.id]
            return Tool(
                name=tool_spec.name,
                description=self._data.tools[tool_spec.id].description,
                input_json_schema=cast(
                    dict[str, Any], self._data.tools[tool_spec.id].input_json_schema
                ),
                input_adapter=input_adapter,
                output_adapter=output_adapter,
            )

        tools = {tool_spec.name: make_tool(tool_spec) for tool_spec in template.tools}

        if template.output_format.format == "json":
            output_format = cast(
                OutputFormat[Output],
                JsonOutputFormat(
                    format="json",
                    json_schema=template.output_format.json_schema,
                    has_recursive_type=template.output_format.has_recursive_type,
                    type_adapter=output_adapter,
                ),
            )
        else:
            output_format = cast(OutputFormat[Output], TextOutputFormat(format="text"))

        return Prompt(
            meta=meta,
            system_message=system_message,
            user_message=user_message,
            examples=examples,
            tools=tools,
            output_format=output_format,
            template_id=self._template_id,
            _internal=None,
        )


def _get_template_impl(
    id: TemplateId,
    data: _internal.Templates | None,
) -> Template[Any, Any, Any]:
    data = data or _templates_data
    template = data.templates[id]
    return _TemplateImpl(_template_id=id, _template_data=template, _data=data)


class _TemplateOverrider:
    @property
    def templates_data(self) -> dict[str, Any]:
        """Returns the compiled prompt templates data."""
        return _templates_data.model_dump(by_alias=True)

    def apply_overrides(self, overrides: dict[str, Any] | None) -> Prompts:
        """Returns a `Prompts` instance with the given template overrides applied.

        If `overrides` is None, returns the default `prompts` instance.
        """
        if overrides is None:
            return prompts
        overrides_obj = _internal.Templates.model_validate(overrides, by_alias=True)
        del overrides
        if _templates_data.signature != overrides_obj.signature:
            raise ValueError("Signature mismatch")
        return _create_prompts(
            _internal.Templates(
                edition=_templates_data.edition,
                signature=_templates_data.signature,
                templates={**_templates_data.templates, **overrides_obj.templates},
                tools={**_templates_data.tools, **overrides_obj.tools},
                source_files={
                    **_templates_data.source_files,
                    **overrides_obj.source_files,
                },
            )
        )


# Enables dynamic template overrides for rapid prompt iteration, evaluations, and
# automated prompt refinement with coding agents.
#
# When using overrides, inject the resulting Prompts instance as a dependency rather
# than relying on the global 'prompts' variable.
#
# Guide:
#   https://github.com/gepheum/TypePrompt/blob/main/docs/template-overrides.md
template_overrider: Final = _TemplateOverrider()


# Entry point for building prompts.
prompts: Final[Prompts] = _create_prompts(_templates_data)


# To disable linter warnings about unused imports
_ = (Annotated, Never, Union, overload)
del _
